update pages set contenu = '{"gabarit":"implantations","chapeau":"La proximité n’est pas un argument commercial\u00a0: c’est ce qui fait la différence entre une intervention le lendemain matin et une intervention la semaine suivante. Chaque agence couvre son bassin avec ses propres équipes.","chiffres":[],"titreAgences":"Lyon en siège, trois agences à l’international","agences":[],"international":{"titre":"Deux bureaux pour suivre nos clients hors de France.","texte":"Quand un groupe industriel français ouvre un site à l’étranger, il perd souvent son réseau de prestataires. Nos agences de Montréal, Dubaï et Madrid servent d’abord à cela.","image":{"src":"/assets/web/ph-hero-raffinerie.jpg","alt":"Site industriel"},"bureaux":[]},"couverture":{"titre":"Villes et départements couverts","villes":[],"departements":[]}}'::jsonb where path = '/implantations/';
update pages set contenu = jsonb_set(contenu, '{chiffres}', (contenu->'chiffres') || '[{"valeur":"4","libelle":"agences"},{"valeur":"1\u00a0h","libelle":"pour un premier rappel","accent":true},{"valeur":"2","libelle":"bureaux à l’international"}]'::jsonb) where path = '/implantations/';
update pages set contenu = jsonb_set(contenu, '{agences}', (contenu->'agences') || '[{"nom":"Siège & agence de Lyon","badge":"Siège","lieu":"Écully (69)","adresses":["129 chemin du Moulin Carron, 69130 Écully"],"rayon":"France entière, via nos hubs de techniciens à Paris, Lille, Marseille, Toulouse, Strasbourg, Nantes et Lyon","role":"Direction, chargés d’affaires, coordination des opérations, recrutement et évaluation des techniciens","siege":true},{"nom":"Agence de Montréal","badge":"International","lieu":"Québec, Canada","rayon":"Québec et Ontario","role":"Suivre nos clients industriels sur leurs sites nord-américains"},{"nom":"Agence de Dubaï","badge":"International","lieu":"Émirats arabes unis","rayon":"Golfe et Moyen-Orient","role":"Projets de montage et de transfert, appui aux groupes implantés dans la zone"},{"nom":"Agence de Madrid","badge":"International","lieu":"Espagne","rayon":"Péninsule ibérique","role":"Maintenance et travaux pour les sites espagnols et portugais de nos clients"}]'::jsonb) where path = '/implantations/';
update pages set contenu = jsonb_set(contenu, '{international,bureaux}', (contenu->'international'->'bureaux') || '[{"nom":"Dubaï","lignes":["Level 20, 48 Burj Tower, Downtown","Golfe et Moyen-Orient"]},{"nom":"Montréal","lignes":["2020 route Transcanadienne, Dorval, Québec","Amérique du Nord"]}]'::jsonb) where path = '/implantations/';
update pages set contenu = jsonb_set(contenu, '{couverture,villes}', (contenu->'couverture'->'villes') || '[{"libelle":"Lyon","href":"/implantations/lyon/"},{"libelle":"Paris","href":"/implantations/paris/"},{"libelle":"Nantes","href":"/implantations/nantes/"},{"libelle":"Strasbourg","href":"/implantations/strasbourg/"},{"libelle":"Toulouse","href":"/implantations/toulouse/"},{"libelle":"Bordeaux","href":"/implantations/toulouse/bordeaux/"},{"libelle":"Rennes","href":"/implantations/nantes/rennes/"},{"libelle":"Grenoble","href":"/implantations/lyon/grenoble/"},{"libelle":"Rouen","href":"/implantations/paris/rouen/"},{"libelle":"Brest","href":"/implantations/nantes/brest/"}]'::jsonb) where path = '/implantations/';
update pages set contenu = jsonb_set(contenu, '{couverture,departements}', (contenu->'couverture'->'departements') || '[{"libelle":"Rhône","href":"/implantations/lyon/rhone/"},{"libelle":"Bas-Rhin","href":"/implantations/strasbourg/alsace/"},{"libelle":"Haute-Garonne","href":"/implantations/toulouse/haute-garonne/"},{"libelle":"Nord","href":"/implantations/maintenance-industrielle-valenciennes/"},{"libelle":"Loire-Atlantique","href":"/implantations/nantes/loire-atlantique/"},{"libelle":"Drôme","href":"/implantations/lyon/valence/"},{"libelle":"Charente","href":"/implantations/toulouse/charente/"},{"libelle":"Essonne","href":"/implantations/paris/essonne/"},{"libelle":"Gironde","href":"/implantations/toulouse/gironde/"},{"libelle":"Haute-Savoie","href":"/implantations/lyon/haute-savoie/"}]'::jsonb) where path = '/implantations/';
